entries[2553] = { ["name"] = "Rezept: Elixier der schwachen Beweglichkeit", ["text"] = "Benötigt Alchimie (50)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der schwachen Beweglichkeit.\nAus Flitzdistel für Tempo und zerstoßenem Silberblatt zur Verstärkung wird ein Trank gebraut, der die natürliche Beweglichkeit erweitert.\nVerkaufspreis:\nElixier der schwachen Beweglichkeit\nBenötigt Stufe 2\nBenutzen: Erhöht die Beweglichkeit 1 Stunde lang um 4. Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Flitzdistel , Silberblatt , Leere Phiole" }
entries[2554] = { ["name"] = "Ausgedientes Rezept: Elixier der Seelenstärke", ["text"] = "Benötigt Alchimie (50)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der schwachen Seelenstärke.\nVerkaufspreis:\nElixier der schwachen Seelenstärke\nBenötigt Stufe 2\nBenutzen: Erhöht die maximale Gesundheit des Spielers 1 Stunde lang um 27. Wächterelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Erdwurzel (2), Friedensblume , Leere Phiole" }
entries[2555] = { ["name"] = "Rezept: Hurtigkeitstrank", ["text"] = "Benötigt Alchimie (60)\nBenutzen: Lehrt Euch die Herstellung eines Hurtigkeitstranks.\nVerkaufspreis:\nHurtigkeitstrank\nBenötigt Stufe 5\nBenutzen: Erhöht das Lauftempo 15 Sek. lang um 50%. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Flitzdistel , Wilddornrose , Leere Phiole" }
entries[2556] = { ["name"] = "Rezept: Elixier der Sprachen", ["text"] = "Benötigt Alchimie (70)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der Sprachen.\nVerkaufspreis:\nElixir of Tongues (NYI)\nBenötigt Stufe 5\n\"Dieser Trank hat erst eine Wirkung, wenn wir Sprachen hinzufügen.\"\nVerkaufspreis:\nBenötigt Erdwurzel (2), Maguskönigskraut (2), Leere Phiole" }
