entries[2697] = { ["name"] = "Rezept: Pastete aus Geiferzahnleber", ["text"] = "Benötigt Kochkunst (50)\nBenutzen: Lehrt Euch, wie man eine Pastete aus Geiferzahnleber zubereitet.\nVerkaufspreis:\nPastete aus Geiferzahnleber\nBenötigt Stufe 5\nBenutzen: Stellt im Verlauf von 21 Sek. 243.6 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 4 Ausdauer und Willenskraft.\nVerkaufspreis:\nBenötigt Geiferzahnleber , Milde Gewürze" }
entries[2698] = { ["name"] = "Rezept: Gekochte Krebsschere", ["text"] = "Benötigt Kochkunst (85)\nBenutzen: Lehrt Euch, wie man eine gekochte Krebsschere zubereitet.\nVerkaufspreis:\nGekochte Krebsschere\nBenötigt Stufe 5\nBenutzen: Stellt 21 Sek. lang 294 Gesundheit und 294 Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:\nBenötigt Kriecherklaue , Milde Gewürze" }
entries[2699] = { ["name"] = "Rezept: Rotkammgulasch", ["text"] = "Benötigt Kochkunst (100)\nBenutzen: Lehrt Euch, wie man ein köstliches Rotkammgulasch zubereitet.\nVerkaufspreis:\nRotkammgulasch\nBenötigt Stufe 10\nBenutzen: Stellt im Verlauf von 24 Sek. 552 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 6 Ausdauer und Willenskraft.\nVerkaufspreis:\nBenötigt Knuspriges Spinnenfleisch , Zähes Kondorfleisch" }
entries[2700] = { ["name"] = "Rezept: Saftige Schweinerippchen", ["text"] = "Benötigt Kochkunst (110)\nBenutzen: Lehrt Euch, wie man saftige Schweinerippchen zubereitet.\nVerkaufspreis:\nSaftige Schweinerippchen\nBenötigt Stufe 10\nBenutzen: Stellt im Verlauf von 24 Sek. insgesamt 552 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:\nBenötigt Eberrippchen (2), Scharfe Gewürze" }
entries[2701] = { ["name"] = "Rezept: Gewürzter Wolfskebab", ["text"] = "Benötigt Kochkunst (100)\nBenutzen: Lehrt Euch, wie man einen gewürzten Wolfskebab zubereitet.\nVerkaufspreis:\nGewürzter Wolfskebab\nBenötigt Stufe 15\nBenutzen: Stellt im Verlauf von 24 Sek. 552 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 6 Ausdauer und Willenskraft.\nVerkaufspreis:\nBenötigt Magere Wolfflanke (2), Würzkräuter aus Sturmwind" }
