entries[2881] = { ["name"] = "Pläne: Runenverzierte Kupferbrustplatte", ["text"] = "Benötigt Schmiedekunst (80)\nBenutzen: Lehrt Euch die Herstellung einer runenverzierten Kupferbrustplatte.\nVerkaufspreis:\nRunenverzierte Kupferbrustplatte\nWird beim Anlegen gebunden\nBrust Kette\n162 Rüstung\n+4 Stärke\n+3 Ausdauer\nHaltbarkeit 80 / 80\nBenötigt Stufe 13\nVerkaufspreis:\nBenötigt Kupferbarren (12), Schattenedelstein , Rauer Schleifstein (2)" }
entries[2882] = { ["name"] = "Pläne: Bronzene Schultern mit Versilberung", ["text"] = "Benötigt Schmiedekunst (125)\nBenutzen: Lehrt Euch die Herstellung von bronzenen Schultern mit Versilberung.\nVerkaufspreis:\nBronzene Schultern mit Versilberung\nWird beim Anlegen gebunden\nSchulter Kette\n137 Rüstung\n+3 Stärke\n+3 Ausdauer\n+3 Willenskraft\nHaltbarkeit 55 / 55\nBenötigt Stufe 20\nVerkaufspreis:\nBenötigt Bronzebarren (8), Silberbarren (2), Grober Schleifstein (2)" }
entries[2883] = { ["name"] = "Pläne: Tödlicher Bronzepoignard", ["text"] = "Benötigt Schmiedekunst (125)\nBenutzen: Lehrt Euch die Herstellung eines tödlichen Bronzepoignards.\nVerkaufspreis:\nTödlicher Bronzepoignard\nWird beim Anlegen gebunden\nEinhändig Dolch\n16 - 30 Schaden Tempo 1.80\n(12.78 Schaden pro Sekunde)\n+4 Beweglichkeit\nHaltbarkeit 45 / 45\nBenötigt Stufe 20\nVerkaufspreis:\nBenötigt Bronzebarren (4), Starker Fluxus , Hurtigkeitstrank , Schattenedelstein (2), Grober Schleifstein (2), Mittleres Leder (2)" }
