entries[3088] = { ["name"] = "Buch der Verjüngung IV", ["text"] = "Klassen: Druide\nBenötigt Stufe 22\nBenutzen: Lehrt 'Verjüngung' (Rang 4).\nHeilt beim Ziel 12 Sek. lang insgesamt 180 Schaden.\nVerkaufspreis:" }
entries[3089] = { ["name"] = "Foliant des Flammenstoßes", ["text"] = "Klassen: Magier\nBenötigt Stufe 16\nBenutzen: Lehrt 'Flammenstoß' (Rang 1).\nLässt eine Feuersäule niedergehen, die alle Feinde im Gebiet verbrennt und ihnen zunächst 55 bis 71 Feuerschaden und zusätzlich 8 Sek. lang insgesamt 48 Feuerschaden zufügt.\nVerkaufspreis:" }
entries[3090] = { ["name"] = "Foliant des Frostblitzes", ["text"] = "Klassen: Magier\nBenötigt Stufe 4\nBenutzen: Lehrt 'Frostblitz' (Rang 1).\nSchleudert einen Frostblitz auf den Feind, der 20 bis 22 Frostschaden verursacht und 5 Sek. lang das Bewegungstempo um 40% reduziert.\nVerkaufspreis:" }
entries[3091] = { ["name"] = "Foliant der arkanen Intelligenz II", ["text"] = "Klassen: Magier\nBenötigt Stufe 14\nBenutzen: Lehrt 'Arkane Intelligenz' (Rang 2).\nErhöht 30 Min. lang die Intelligenz des Ziels um 7.\nVerkaufspreis:" }
entries[3092] = { ["name"] = "Foliant des Flammenstoßes III", ["text"] = "Klassen: Magier\nBenötigt Stufe 32\nBenutzen: Lehrt 'Langsamkeit' (Rang 2).\nVerlangsamt 15 Sek. lang die Bewegung des Feindes um 60% und sein Angriffstempo um 54%.\nVerkaufspreis:" }
entries[3093] = { ["name"] = "Foliant des Flammenstoßes II", ["text"] = "Klassen: Magier\nBenötigt Stufe 24\nBenutzen: Lehrt 'Flammenstoß' (Rang 2).\nLässt eine Feuersäule niedergehen, die alle Feinde im Gebiet verbrennt und ihnen zunächst 100 bis 126 Feuerschaden und zusätzlich 8 Sek. lang insgesamt 88 Feuerschaden zufügt.\nVerkaufspreis:" }
entries[3094] = { ["name"] = "Foliant des Feuerschlages II", ["text"] = "Klassen: Magier\nBenötigt Stufe 14\nBenutzen: Lehrt 'Feuerschlag' (Rang 2).\nÜberzieht den Feind mit 62 bis 76 Feuerschaden.\nVerkaufspreis:" }
entries[3095] = { ["name"] = "Foliant des Feuerschlages III", ["text"] = "Klassen: Magier\nBenötigt Stufe 22\nBenutzen: Lehrt 'Feuerschlag' (Rang 3).\nÜberzieht den Feind mit 110 bis 134 Feuerschaden.\nVerkaufspreis:" }
entries[3096] = { ["name"] = "Foliant des Federfalls", ["text"] = "Klassen: Magier\nBenötigt Stufe 12\nBenutzen: Lehrt 'Federfall'.\nVerlangsamt 30 Sek. lang das Falltempo.\nVerkaufspreis:" }
entries[3097] = { ["name"] = "Foliant des Wasserherbeizauberns II", ["text"] = "Klassen: Magier\nBenötigt Stufe 10\nBenutzen: Lehrt 'Wasser herbeizaubern' (Rang 2).\nZaubert 20 Flaschen frisches Wasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezaubertes frisches Wasser\nHerbeigezauberter Gegenstand\nBenötigt Stufe 5\nBenutzen: Stellt im Verlauf von 21 Sek. insgesamt 437 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[3098] = { ["name"] = "Foliant der Verlangsamung", ["text"] = "Klassen: Magier\nBenötigt Stufe 28\nBenutzen: Lehrt 'Langsam' (Rang 1).\nVerlangsamt 10 Sek. lang die Bewegung des Feindes um 150% und sein Angriffstempo um 35%.\nVerkaufspreis:" }
entries[3099] = { ["name"] = "Foliant der Eisrüstung II", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Eisrüstung' (Rang 2).\nErhöht die Rüstung um 380 und den Frostwiderstand um 9. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an.\nVerkaufspreis:" }
entries[3100] = { ["name"] = "Foliant des Blizzards II", ["text"] = "Klassen: Magier\nBenötigt Stufe 28\nBenutzen: Lehrt 'Blizzard' (Rang 2).\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 Sek. lang insgesamt ( 45 * 8) Frostschaden.\nVerkaufspreis:" }
entries[3101] = { ["name"] = "Foliant der Frostnova III", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Frostnova' (Rang 3).\nFügt in der Nähe des Zaubernden befindlichen Feinden 54 bis 61 Frostschaden zu und friert sie bis zu 8 Sek. lang ein. Erlittener Schaden kann den Effekt unterbrechen.\nVerkaufspreis:" }
entries[3102] = { ["name"] = "Foliant der arkanen Intelligenz III", ["text"] = "Klassen: Magier\nBenötigt Stufe 28\nBenutzen: Lehrt 'Arkane Intelligenz' (Rang 3).\nErhöht 30 Min. lang die Intelligenz des Ziels um 15.\nVerkaufspreis:" }
