entries[3113] = { ["name"] = "Kodex des Heiligen Wortes: Schild", ["text"] = "Klassen: Priester\nBenötigt Stufe 6\nBenutzen: Lehrt 'Heiliges Wort: Schild' (Rang 1).\nNutzt die Seelenkraft des Gruppenmitglieds zum Abschirmen und absorbiert dabei 48 Schaden. Hält 30 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 Sek. lang nicht wieder abgeschirmt werden.\nVerkaufspreis:" }
entries[3114] = { ["name"] = "Kodex des Schattenwortes: Verwirrung", ["text"] = "Klassen: Priester\nBenötigt Stufe 24\nBenutzen: Lehrt 'Schattenwort: Verwirrung' (Rang 1).\nVerkaufspreis:" }
entries[3115] = { ["name"] = "Kodex der Erneuerung IV", ["text"] = "Klassen: Priester\nBenötigt Stufe 26\nBenutzen: Lehrt 'Erneuerung' (Rang 4).\nHeilt das Ziel 15 Sek. lang um insgesamt 245.\nVerkaufspreis:" }
entries[3116] = { ["name"] = "Kodex des Heiligen Wortes: Schild II", ["text"] = "Klassen: Priester\nBenötigt Stufe 12\nBenutzen: Lehrt 'Heiliges Wort: Schild' (Rang 2).\nNutzt die Seelenkraft des Gruppenmitglieds zum Abschirmen und absorbiert dabei 94 Schaden. Hält 30 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 Sek. lang nicht wieder abgeschirmt werden.\nVerkaufspreis:" }
